table ip filter {
  chain input {
    type filter hook input priority 0; policy drop;
    ct state established,related accept
  }

  chain forward {
    type filter hook forward priority 0; policy drop;
    ct state established,related accept

    # Internal Network can access DMZ
    iif "eth1" ip saddr 10.0.0.0/16 oif "eth0" ip daddr 172.16.20.0/24 accept

    # Internal Network can access Internet only via Application Proxy
    iif "eth1" ip saddr 10.0.0.0/16 ip daddr 172.16.20.50 accept
    ip saddr 172.16.20.50 oif "wan0" accept

    # DMZ Servers (excluding Webservers) can access Internet
    ip saddr {172.16.20.20, 172.16.20.30, 172.16.20.100} oif "wan0" accept

    # Load Balancer communicates with Webservers
    ip saddr 172.16.20.100 ip daddr {172.16.20.10, 172.16.20.11} accept

    # Management Network can manage DMZ Servers via SSH and RDP
    iif "eth1" ip saddr 10.1.0.0/24 ip daddr 172.16.20.0/24 tcp dport {22, 3389} accept
  }

  chain output {
    type filter hook output priority 0; policy drop;
    ct state established,related accept
  }
}
@@@END_FILE@@@

