        ip saddr 10.1.0.0/24 tcp dport {22, 3389} accept

        # Prevent DMZ from accessing Internal Network
        ip saddr 172.16.20.0/24 ip daddr 10.0.0.0/16 drop
    }

    chain output {
        type filter hook output priority 0;
        policy drop;
        ct state established, related accept
    }
}
