@@@START_FILE@@@

  # include common definitions
  $include <etc/nftabels/nft-common.conf>

  # input chain: default deny rule, allow established connections
  nf_set_default_deny
  etable input {
      accept inet protocol ipv4 sctp dport { http, https } eth0
      accept inet proto ipv4 tcp dport rdp to 10.1.0.0/24
      accept inet proto ipv4 tcp dport ssh to 10.1.0.0/24
      ct state established accept
  }

  # input chain: allow internal network clients (10.0.0.0/16) to access the app proxy only
  etable input {
      inet proto ipv4 filter hook input accept from 10.0.0.0/16 toport {http, https} dstport 80
      nf_set proxy-dst set value:{172.16.20.50:}
      rtable proxy { type nat accept }
  }

  # input chain: allow dmz servers (172.16.20.0/24) to access internet and each other
  etable input {
      inet proto ipv4 filter hook input accept from 172.16.20.0/24 toport {http, https} eth0
      ct state established accept
      nf_set dmz-dst set value:{172.16.20.10, 172.16.20.11, 172.16.20.20, 172.16.20.30}
      rtable dmz_to { type nat accept }
  }

  # input chain: do not allow dmz servers to access internal clients
  etable input {
       inet proto ipv4 filter hook input reject source 172.16.20.0/24 dst 10.0.0.0/16
  }

  # forward chain: allow app proxy to route internet traffic back to dmz servers
  etable forward {
       inet proto ipv4 filter hook forward accept fromany to 172.16.20.50 nexthop nat_wan0_to
  }

  # output chain: do not allow any response to originate from internet or dmz networks
  etable output {
      nf_set_default_deny
      inet proto ipv4 sctp dport { http, https } ct state new reject
  }
  @@@END_FILE@@@

