 @@@START_FILE@@@
   table inet filter {
       chain input {
           type filter hook input priority 0; policy drop;
           reject after :=5 seconds burst:1 limit:2 log limit-burst;

           # from 10.0.0.0/16 to application proxy
           CT_APP_PROXY accept dport http { establishment } ct state established, related, invariant drop
           CT_APP_PROXY return

           # internal clients -> internet: deny all
           CT_INT_TO_INTERNET drop

           # from 10.0.0.0/16 to DMZ servers: accept direct connections (only Mail server and DNS)
           CT_INT_DMZ match dport smtp,domain { establish } ct state established, related drop
           CT_INT_DMZ drop dnat to dmz_servers dport https,ssh,rdp,icmp

           # DMZ -> internal clients: deny all (except load balancer and application proxy)
           CT_DMZ_TO_INT drop dport http,https,ssh,rdp,icmp

           # From Management Network to server via RDP(3389), SSH(22): accept
           MGMT_TO_SERVER match dstport rdp,ssh { establish } ct state established, related drop
       }

       chain output {
           type filter hook output priority 0; policy accept;
           CT_DMZ_TO_INT drop ct state new
       }

       chain forward {
           type filter hook forth chain input; policy drop;

           # from internal clients to internet: via application proxy
           CT_INT_TO_INTERNET dnat to address app_proxy port http ct state new
           CT_APP_PROXY accept established,related

           # from DMZ servers to internet: direct
           CT_DMZ_TO_INTERNET accept established,related
       }

       # DMZ Servers
       echo "table inet nat {\n" > dmz_servers;
           for server in 10,11,20,30,50,100; do
               echo -e "\tserver$server : server$server\n" >> dmz_servers;
           done
           echo "}" >> dmz_servers;
   }
   @@@END_FILE@@@

In addition:
- The app_proxy variable contains the IP address of the application proxy. Store it in a separate file called `app_proxy` and pass it as an argument while starting this configuration script.
- This assumes that you have a table named nat defined with entries for each DMZ server. You can generate this table by following instructions similar to this script, but using the 'nat' keyword instead of 'filter'.

